// 1. Dependencies dans build.gradle
// implementation "com.google.dagger:hilt-android:2.55"
// KSP "com.google.dagger:hilt-android-compiler:2.55"

// 2. Application class
@HiltAndroidApp
class TodoApplication : Application() {
    // Hilt gère l'initialisation
}

// 3. Database Module
@Module
@InstallIn(SingletonComponent::class)
object DatabaseModule {
    @Provides
    @Singleton
    fun provideTaskDatabase(context: Context): TaskDatabase =
        Room.databaseBuilder(
            context.applicationContext,
            TaskDatabase::class.java,
            "task_database"
        ).fallbackToDestructiveMigration().build()

    @Provides
    fun provideTaskDao(database: TaskDatabase): TaskDao = database.taskDao()
}

// 4. Repository Module
@Module
@InstallIn(SingletonComponent::class)
object RepositoryModule {
    @Provides
    fun provideLocalDataSource(taskDao: TaskDao): LocalTaskDataSource =
        LocalTaskDataSource(taskDao)

    @Provides
    fun provideRemoteDataSource(api: TaskApi): RemoteTaskDataSource =
        RemoteTaskDataSource(api)

    @Provides
    fun provideTaskRepository(
        localDataSource: LocalTaskDataSource,
        remoteDataSource: RemoteTaskDataSource
    ): TaskRepository = TaskRepositoryImpl(localDataSource, remoteDataSource)
}

// 5. ViewModel
class TodoViewModel @Inject constructor(
    private val getTasks: GetTasks,
    private val addTask: AddTask
) : ViewModel() {
    // ...
}

// Bonus: Fournir l'Api avec Retrofit
@Module
@InstallIn(SingletonComponent::class)
object NetworkModule {
    @Provides
    @Singleton
    fun provideRetrofit(): Retrofit = Retrofit.Builder()
        .baseUrl("https://api.example.com/")
        .addConverterFactory(GsonConverterFactory.create())
        .build()

    @Provides
    fun provideTaskApi(retrofit: Retrofit): TaskApi = retrofit.create(TaskApi::class.java)
}

